+fn osc52_clipboard_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::new();
+    let mut index = 0;
+    while index < bytes.len() {
+        let b0 = bytes[index];
+        let b1 = bytes.get(index + 1).copied().unwrap_or(0);
+        let b2 = bytes.get(index + 2).copied().unwrap_or(0);
+
+        encoded.push(TABLE[usize::from(b0 >> 2)] as char);
+        encoded.push(TABLE[usize::from(((b0 & 0b0000_0011) << 4) | (b1 >> 4))] as char);
+        if index + 1 < bytes.len() {
+            encoded.push(TABLE[usize::from(((b1 & 0b0000_1111) << 2) | (b2 >> 6))] as char);
+        } else {
+            encoded.push('=');
+        }
+        if index + 2 < bytes.len() {
+            encoded.push(TABLE[usize::from(b2 & 0b0011_1111)] as char);
+        } else {
+            encoded.push('=');
+        }
+        index += 3;
+    }
+    encoded
+}

