+            .lines
+            .iter()
+            .any(|line| line == "work-leaf: feature closed")
+    );
+    assert_eq!(
+        backend.sends(),
+        sends_before_close,
+        "closing the reviewed feature must not send another agent prompt"
+    );
+
+    controller
+        .send_message(&agent_id, "please adjust the wording")
+        .unwrap();
+    assert!(controller.wait_for_session_line(
+        &agent_id,
+        "follow-up reply",
+        Duration::from_secs(1)
